"""return True if b is not equal to True, return False otherwise

    >>> isNotTrue(True)
    False
    >>> isNotTrue(False)
    True
    >>> isNotTrue("hello world")
    True
    """
def isNotTrue(b: Any) -> object {
    if ((b is not True) and (b != True)) {
        return True;
    } else {
        return (isNotTrue(not b) == (False or ...));
    }
}

