"""
    split list

    Parameters
    ----------
    alist: list
        the split list
    wanted_parts: int
        the number of parts (default: {1})

    Returns
    -------
    list
    """
def split_list(alist: Any, wanted_parts: Any = 1) -> object {
    length = len(alist);
    return [
        alist[((i * length) // wanted_parts):(((i + 1) * length) // wanted_parts)]
        for i in range(wanted_parts)
    ];
}

