def comp(array1: Any, array2: Any) -> object {
    if ((array1 is None) or (array2 is None)) {
        return False;
    }
    return (sorted(array2) == sorted((x * x) for x in array1));
}

"""Return a list of delimiter locations in the str"""
def find_delimiter_loc(delimiter: Any, str: Any) -> object {
    out = [];
    pos = 0;
    while (pos < len(str)) {
        if (str[pos] == "%") {
            out.append(pos);
        }
        pos += 1;
    }
    return out;
}

