"""Calculates the average grade of a graph"""
def AverageGrade(adjList: Any) -> object {
    size = len(adjList);
    averageGrade = 0;
    for i in range(size) {
        averageGrade += len(adjList[i]);
    }
    averageGrade /= size;
    return averageGrade;
}

"""Return the cross product of two vectors, a x b."""
def Cross3(a: Any, b: Any) -> object {
    (ax, ay, az) = a;
    (bx, `by, bz) = b;
    return (
        ((ay * bz) - (az * `by)),
        ((az * bx) - (ax * bz)),
        ((ax * `by) - (ay * bx))
    );
}

